<script lang="ts">
 import {api} from './lib/api';import * as c from './lib/crypto';
 let {connected,action='connect'}:{connected:()=>Promise<void>;action?:'connect'|'replica-copy'}=$props();
 let reviewed=$state(false);let locationKey=$state('');
 let kind=$state('github'),endpoint=$state('https://api.github.com'),owner=$state(''),repository=$state(''),branch=$state('main'),namespace=$state('nightbuoy'),bucket=$state(''),region=$state('us-east-1'),token=$state(''),accessKey=$state(''),secretKey=$state(''),salt=c.b64(c.random()),connection:any=$state(null),busy=$state(false),error=$state('');
 const destination=$derived(connection?.primary??{kind,endpoint,owner,repository,branch,namespace,bucket,region,salt});
 $effect(()=>{const next=c.canonical(destination);if(locationKey!==next){locationKey=next;token='';accessKey='';secretKey='';reviewed=false;}});
 async function open(){if(!reviewed){error='Review and trust the exact backend destination first.';return;}busy=true;error='';try{const primary=connection?.primary??{kind,endpoint,owner,repository,branch,namespace,bucket,region,salt};const id=c.b64(Uint8Array.from((await c.hash(c.canonical(primary))).match(/../g)!,x=>parseInt(x,16)));await api('/api/'+action,{...(action==='connect'?{connection:connection??{version:1,primary,replicas:[],community:''}}:{backend:primary}),access:{backend:id,token,access_key:accessKey,secret_key:secretKey}});token='';accessKey='';secretKey='';await connected();}catch(e){error=String(e);}finally{busy=false;}}
 async function read(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>128000)throw Error('Connection file too large.');token='';accessKey='';secretKey='';reviewed=false;const parsed=JSON.parse(await f.text());if(parsed?.version!==1||!parsed.primary||typeof parsed.primary.kind!=='string'||typeof parsed.primary.endpoint!=='string'||!Array.isArray(parsed.replicas)||parsed.replicas.length>50)throw Error('Choose a NightBuoy forum connection file. Identity recovery files belong in the sign-in screen.');connection=parsed;}
</script>
<section class="card setup"><h1>{action==='connect'?'Your forum lives on your backends.':'Copy verified history to an independent backend'}</h1><p>Open a connection file to resume a forum, or choose an empty storage namespace to create one. This client uses memory; confirmed history lives remotely.</p><label>Forum connection file<input type="file" accept=".json,application/json" onchange={e=>read(e).catch(e=>error=String(e))}/></label>
{#if connection}<p>Connection loaded. Verify the community fingerprint independently: <code>{connection.community||'New community'}</code></p><button onclick={()=>connection=null}>Use a different backend</button>{:else}
<label>Storage provider<select bind:value={kind} onchange={()=>endpoint=kind==='github'?'https://api.github.com':''}><option value="github">GitHub</option><option value="forgejo">Forgejo</option><option value="s3">S3 compatible</option></select></label><label>HTTPS or onion API origin<input bind:value={endpoint}/></label>
{#if kind==='s3'}<label>Bucket<input bind:value={bucket}/></label><label>Region<input bind:value={region}/></label>{:else}<label>Repository owner<input bind:value={owner}/></label><label>Repository name<input bind:value={repository}/></label><label>Branch (must already exist)<input bind:value={branch}/></label>{/if}<label>Empty namespace for a new forum<input bind:value={namespace}/></label>{/if}
<p class="fingerprint">Provider destination: <strong>{destination.endpoint}</strong><br/>Repository: {destination.owner}/{destination.repository} · {destination.branch}<br/>Bucket: {destination.bucket} · {destination.region}<br/>Namespace: {destination.namespace}</p><label class="check"><input type="checkbox" bind:checked={reviewed}/> I trust this exact destination to receive my scoped credentials.</label>
{#if (connection?.primary?.kind??kind)==='s3'}<label>Your scoped access key<input type="password" bind:value={accessKey} autocomplete="off"/></label><label>Your secret key<input type="password" bind:value={secretKey} autocomplete="off"/></label>{:else}<label>Your scoped repository token<input type="password" bind:value={token} autocomplete="off"/></label>{/if}<p class="hint">Leave access blank for publicly readable encrypted copies. Posting requires your own provider permission as well as forum membership. Credentials stay in companion memory; never put an owner's token in a shared connection file. Download the connection file after creation.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="primary" disabled={busy||!reviewed} onclick={open}>{action==='connect'?'Connect to storage':'Copy encrypted history & verify'}</button></section>
